I = importlib

import currency as tau

balances = Hash(default_value=0)
metadata = Hash()

tax = Variable()
total_supply = Variable()
swap_enabled = Variable()

SWAP_FACTOR = 100
RSWP_CONTRACT = 'con_rocketswap_official_v1_1'
BURN_ADDRESS = 'internal_burn_address'

@construct
def seed():
    balances[ctx.caller] = 0

    metadata['token_name'] = "TTTest"
    metadata['token_symbol'] = "TTTest"
    metadata['owner'] = ctx.caller

    tax.set(2)

    swap_enabled.set(True)
    total_supply.set(0)

@export
def change_metadata(key: str, value: Any):
    assert_owner(); metadata[key] = value

@export
def transfer(amount: float, to: str):
    assert amount > 0, 'Cannot send negative balances!'
    assert balances[ctx.caller] >= amount, 'Not enough coins to send!'

    balances[ctx.caller] -= amount
    balances[to] += amount

    if ctx.caller == RSWP_CONTRACT or to == RSWP_CONTRACT:
        pay_tax(amount)

@export
def approve(amount: float, to: str):
    assert amount > 0, 'Cannot send negative balances!'
    balances[ctx.caller, to] += amount

@export
def transfer_from(amount: float, to: str, main_account: str):
    assert amount > 0, 'Cannot send negative balances!'
    assert balances[main_account, ctx.caller] >= amount, f'You approved {balances[main_account, ctx.caller]} but need {amount}'
    assert balances[main_account] >= amount, 'Not enough coins to send!'

    balances[main_account, ctx.caller] -= amount
    balances[main_account] -= amount
    balances[to] += amount

    if ctx.caller == RSWP_CONTRACT or to == RSWP_CONTRACT:
        pay_tax(amount)

def pay_tax(amount: float):
    tax_amount = int(amount / 100 * tax.get())

    if tax_amount > 0:
        prices = ForeignHash(
            foreign_contract=RSWP_CONTRACT, 
            foreign_name='prices')

        if prices[ctx.this] == 0:
            return

        tau.transfer_from(
            main_account=ctx.signer, 
            amount=amount * prices[ctx.this], 
            to=ctx.this)

        difference = ((int(balances[ctx.signer] - tax_amount)) * -1) + 1

        error = f'Not enough coins to pay for {metadata["token_symbol"]} tax. Missing {difference} {metadata["token_symbol"]}'
        assert balances[ctx.signer] >= tax_amount, error

        balances[ctx.this] += tax_amount
        balances[ctx.signer] -= tax_amount

@export
def swap_doug(doug_amount: float):
    assert swap_enabled.get() == True, 'Swapping DOUG for TTest currently disabled'
    assert doug_amount > 0, 'Cannot swap negative balances!'

    I.import_module('con_doug_lst001').transfer_from(
        main_account=ctx.caller, 
        amount=doug_amount, 
        to=BURN_ADDRESS)

    swap_amount = doug_amount / SWAP_FACTOR
    total_supply.set(total_supply.get() + swap_amount)
    balances[ctx.caller] += swap_amount

@export
def set_tax(tax_in_percent: float):
    assert_owner(); tax.set(tax_in_percent)

@export
def swap_enabled(enabled: bool):
    assert_owner(); swap_enabled.set(enabled)

@export
def withdraw_token(contract: str, amount: float):
    assert_owner(); I.import_module(contract).transfer(amount, ctx.caller)

@export
def withdraw_lp(contract: str, amount: float):
    assert_owner(); I.import_module(RSWP_CONTRACT).transfer_liquidity(contract, ctx.caller, amount)

@export
def burn(amount: float):
    assert amount > 0, 'Cannot burn negative amount!'
    assert balances[ctx.caller] >= amount, 'Not enough coins to burn!'

    balances[BURN_ADDRESS] += amount
    balances[ctx.caller] -= amount

@export
def circulating_supply():
    return int(total_supply.get() - balances[BURN_ADDRESS])

@export
def total_supply():
    return int(total_supply.get())

def assert_owner():
    assert ctx.caller == metadata['owner'], 'Only executable by owner!'
